package cue

import (
	"os"
	"testing"
)

func FuzzValidate(f *testing.F) {
	testcases := []string{"testdata/valid.yml", "testdata/invalid.yml"}

	for _, tc := range testcases {
		b, _ := os.ReadFile(tc)
		f.Add(b)
	}

	f.Fuzz(func(t *testing.T, in []byte) {
		validator, err := NewFeaturesValidator()
		if err != nil {
			// only care about errors from Validating
			t.Skip()
		}

		if _, err := validator.Validate("foo", in); err != nil {
			// we only care about panics
			t.Skip()
		}
	})
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"

	"github.com/spf13/cobra"
	"go.flipt.io/flipt/internal/cue"
)

type validateCommand struct {
	issueExitCode int
	format        string
}

const (
	jsonFormat = "json"
	textFormat = "text"
)

func newValidateCommand() *cobra.Command {
	v := &validateCommand{}

	cmd := &cobra.Command{
		Use:   "validate",
		Short: "Validate flipt flag state (.yaml, .yml) files",
		Run:   v.run,
	}

	cmd.Flags().IntVar(&v.issueExitCode, "issue-exit-code", 1, "Exit code to use when issues are found")

	cmd.Flags().StringVarP(
		&v.format,
		"format", "F",
		"text",
		"output format: json, text",
	)

	return cmd
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	for _, arg := range args {
		f, err := os.ReadFile(arg)
		if err != nil {
			fmt.Println(err)
			os.Exit(1)
		}

		res, err := validator.Validate(arg, f)
		if err != nil && !errors.Is(err, cue.ErrValidationFailed) {
			fmt.Println(err)
			os.Exit(1)
		}

		if len(res.Errors) > 0 {
			if v.format == jsonFormat {
				if err := json.NewEncoder(os.Stdout).Encode(res); err != nil {
					fmt.Println(err)
					os.Exit(1)
				}
				os.Exit(v.issueExitCode)
				return
			}

			fmt.Println("Validation failed!")

			for _, e := range res.Errors {
				fmt.Printf(
					`
- Message  : %s
  File     : %s
  Line     : %d
  Column   : %d
`, e.Message, e.Location.File, e.Location.Line, e.Location.Column)
			}

			os.Exit(v.issueExitCode)
		}
	}
}
