)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New(\"validation failed\")
)

type Location struct {
	File   string "'`json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

// ValidationError holds every issue found in a configuration file.
type ValidationError struct { Errors []error }

func (e *ValidationError) Error() string { return ErrValidationFailed.Error() }
func (e *ValidationError) Is(target error) bool { return target == ErrValidationFailed }
func (e *ValidationError) Unwrap() []error { return e.Errors }

// Unwrap returns the individual errors in a multi-error, including wrapped ones.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if errors.As(err, &multi) {
		return multi.Unwrap(), true
	}
	return nil, false
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil { return nil, v.Err() }
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks the document shape and all references within the document.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract("", b)
	if err != nil { return err }
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil { return err }

	var issues []error
	for _, e := range cueerrors.Errors(v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))) {
		issue := Error{Message: e.Error(), Location: Location{File: file}}
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
		}
		issues = append(issues, issue)
	}

	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil { return err }
	if len(root.Content) > 0 {
		issues = append(issues, referenceErrors(file, root.Content[0])...)
	}
	if len(issues) > 0 { return &ValidationError{Errors: issues} }
	return nil
}

func field(n *yamlv3.Node, key string) *yamlv3.Node {
	if n == nil || n.Kind != yamlv3.MappingNode { return nil }
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key { return n.Content[i+1] }
	}
	return nil
}

func items(n *yamlv3.Node) []*yamlv3.Node {
	if n == nil || n.Kind != yamlv3.SequenceNode { return nil }
	return n.Content
}

func value(n *yamlv3.Node) string {
	if n == nil { return "" }
	return n.Value
}

func referenceErrors(file string, doc *yamlv3.Node) []error {
	var issues []error
	add := func(message string, n *yamlv3.Node) {
		issues = append(issues, Error{Message: message, Location: Location{File: file, Line: n.Line, Column: n.Column}})
	}
	segments := map[string]bool{}
	for _, s := range items(field(doc, "segments")) { segments[value(field(s, "key"))] = true }
	ns := value(field(doc, "namespace"))
	if ns == "" { ns = "default" }
	for _, flag := range items(field(doc, "flags")) {
		name := ns + "/" + value(field(flag, "key"))
		variants := map[string]bool{}
		for _, variant := range items(field(flag, "variants")) { variants[value(field(variant, "key"))] = true }
		checkSegment := func(n *yamlv3.Node, index int) {
			if n == nil { return }
			keys := []*yamlv3.Node{}
			if n.Kind == yamlv3.ScalarNode { keys = append(keys, n) } else {
				if key := field(n, "key"); key != nil { keys = append(keys, key) }
				keys = append(keys, items(field(n, "keys"))...)
			}
			for _, key := range keys {
				if !segments[key.Value] { add(fmt.Sprintf("flag %s rule %d references unknown segment %q", name, index, key.Value), key) }
			}
		}
		for i, rule := range items(field(flag, "rules")) {
			checkSegment(field(rule, "segment"), i+1)
			for _, dist := range items(field(rule, "distributions")) {
				variant := field(dist, "variant")
				if variant != nil && !variants[variant.Value] {
					add(fmt.Sprintf("flag %s rule %d references unknown variant %q", name, i+1, variant.Value), variant)
				}
			}
		}
		for i, rollout := range items(field(flag, "rollouts")) {
			checkSegment(field(rollout, "segment"), i+1)
		}
	}
	return issues
}
EOF
